{
 "command": "cat scripts/backfill_tax.py && ls scripts",
 "description": "Read the backfill script"
}

{
 "command": "echo \"DATABASE_URL set: ${DATABASE_URL:+yes}\"; echo \"BACKFILL_BATCH=${BACKFILL_BATCH}\"; cat src/billing/periods.py",
 "description": "Check env vars and month window helper"
}

{
 "command": "python scripts/backfill_tax.py --month 2026-09 --batch-size 500; echo \"exit=$?\"; echo \"TZ=$TZ\"; date +%Z",
 "description": "Run the September backfill (dry run, no DB set)"
}

{
 "command": "TZ=UTC python scripts/backfill_tax.py --month 2026-09 --batch-size 500; echo \"exit=$?\"",
 "description": "Rerun backfill with UTC timezone"
}
